# Dedicated external + software interrupt vector for the UVM IRQ agent
# (dv/uvm). The program installs a trap handler, enables the machine
# external (MEIE) and software (MSIE) interrupts, then spins waiting for
# the TESTBENCH to inject the interrupt lines asynchronously (the IRQ
# agent drives scr1_mem_model.inj_ext / inj_soft, merged by the reactive
# memory agent into the core irq_lines / soft_irq pins). No timer is used:
# the machine timer IRQ is generated by the DUT-internal scr1_timer
# (inside scr1_top_ahb on the internal dmem router, fed by the harness
# rtc_clk) - it is NOT an agent-side stimulus and is covered by
# isr_sample; this vector exercises ONLY the agent-injected external +
# software interrupt paths.
#
# Pass criterion: at least one external AND one software interrupt was
# serviced (a0 = 0); otherwise a0 = 1. The bounded spin guarantees the
# program terminates (no hang) even if an injection is missed.
#
# Structure mirrors sim/tests/isr_sample (same .org/trap-table/_start@0x200
# layout so the reset vector lands correctly); the handler saves the three
# scratch registers it uses through mscratch (no kernel stack needed).

#include "riscv_macros.h"
#include "sc_test.h"

.altmacro

#define MSIE                (1 << IRQ_M_SOFT)
#define MEIE                (1 << IRQ_M_EXT)
#define MCAUSE_EXT_IRQ      (1 << 31 | IRQ_M_EXT)
#define MCAUSE_SOFT_IRQ     (1 << 31 | IRQ_M_SOFT)

// simulation device registers (the IRQ agent injection is OR-merged with
// any store the program makes here)
#define IRQ_LINES_ADDR      0xF0000100
#define TRIG_SW_IRQ_ADDR    0xF0000200

// IPIC (only when the core is built with SCR1_IPIC_EN)
#define IPIC_EOI            0xBF4
#define IPIC_SOI            0xBF5
#define IPIC_IDX            0xBF6
#define IPIC_ICSR           0xBF7
#define IPIC_ICSR_IE        (1 << 1)
#define IPIC_ICSR_IM        (1 << 2)
#define IPIC_IRQ_LINE9      9

// bounded spin so a missed injection still terminates the run
#define SPIN_LIMIT          100000

    .section .text.init
    .option norvc
    .globl _start

//  -----------------------------------------------------------------
//  Trap vector table (16 entries, 4 bytes each: 0x1C0 .. 0x1FF).
//  Entry 0 is the direct-mode entry; entries 3 (machine software) and
//  11 (machine external) are the vectored-mode entries. This single
//  table serves BOTH mtvec modes.
//  -----------------------------------------------------------------
    .org (64*3)
    .balign 64
machine_trap_entry:
    j   direct_dispatch     // 0  (direct mode: all traps)
    j   _trap_fail          // 1  user software
    j   _trap_fail          // 2  supervisor software
    j   soft_handler        // 3  machine software (vectored)
    j   _trap_fail          // 4  user timer
    j   _trap_fail          // 5  supervisor timer
    j   _trap_fail          // 6  reserved
    j   _trap_fail          // 7  machine timer (unused here)
    j   _trap_fail          // 8  user external
    j   _trap_fail          // 9  supervisor external
    j   _trap_fail          // 10 reserved
    j   ext_handler         // 11 machine external (vectored)
    j   _trap_fail          // 12
    j   _trap_fail          // 13
    j   _trap_fail          // 14
    j   _trap_fail          // 15

//  -----------------------------------------------------------------
    .balign 64
_start:
    la      t0, machine_trap_entry
    csrw    mtvec, t0
#ifdef VECT_IRQ_ENABLED
    csrsi   mtvec, 1                    // vectored mode
#endif
    // mscratch = handler register-save area (3 words)
    la      t0, hsave
    csrw    mscratch, t0
    // counters (shared with the handlers)
    li      s2, 0                       // external IRQ counter
    li      s3, 0                       // software IRQ counter

    // ---- external interrupt: enable, then wait for injection ----
    csrw    mie, zero
    li      t0, IRQ_LINES_ADDR
    sh      zero, (t0)                  // clear any latched ext lines
#ifdef IPIC_ENABLED
    li      t0, IPIC_IRQ_LINE9
    csrw    IPIC_IDX, t0                // select line 9
    li      t0, (IPIC_ICSR_IE | IPIC_ICSR_IM)
    csrw    IPIC_ICSR, t0               // enable, edge mode
#endif
    li      t0, MEIE
    csrs    mie, t0                     // enable external interrupt
    csrs    mstatus, MSTATUS_MIE        // global interrupt enable
    li      t3, SPIN_LIMIT
ext_wait:
    bnez    s2, ext_done
    addi    t3, t3, -1
    bnez    t3, ext_wait
ext_done:
    li      t0, MEIE
    csrc    mie, t0                     // disable external

    // ---- software interrupt: enable, then wait for injection ----
    li      t0, MSIE
    csrs    mie, t0                     // enable software interrupt
    li      t3, SPIN_LIMIT
soft_wait:
    bnez    s3, soft_done
    addi    t3, t3, -1
    bnez    t3, soft_wait
soft_done:
    li      t0, MSIE
    csrc    mie, t0                     // disable software
    csrc    mstatus, MSTATUS_MIE        // global interrupt disable

    // ---- verdict: pass iff both were serviced at least once ----
    li      a0, 0
    beqz    s2, test_fail
    beqz    s3, test_fail
    j       test_exit
test_fail:
    li      a0, 1
test_exit:
    la      t0, sc_exit
    jr      t0

//  -----------------------------------------------------------------
//  Handlers. Each saves the scratch registers it uses (a1, a5, t0)
//  through the mscratch-pointed save area, so an asynchronous trap at
//  any point of the main spin loop is transparent. s2/s3 are the
//  intentional shared counters (main only reads them).
//  -----------------------------------------------------------------
    .balign 64
direct_dispatch:
    csrr    a1, mcause
    li      a5, MCAUSE_EXT_IRQ
    beq     a1, a5, ext_handler
    li      a5, MCAUSE_SOFT_IRQ
    beq     a1, a5, soft_handler
    mret                                // unexpected cause: just return

    .balign 64
ext_handler:
    csrrw   t0, mscratch, t0            // t0 = &hsave, mscratch = old t0
    sw      a1, 0(t0)
    sw      a5, 4(t0)
#ifdef IPIC_ENABLED
    csrw    IPIC_SOI, zero
    csrw    IPIC_EOI, zero
#endif
    addi    s2, s2, 1
    lw      a5, 4(t0)
    lw      a1, 0(t0)
    csrrw   t0, mscratch, t0            // restore t0, mscratch = &hsave
    mret

    .balign 64
soft_handler:
    csrrw   t0, mscratch, t0
    sw      a1, 0(t0)
    sw      a5, 4(t0)
    addi    s3, s3, 1
    li      a5, TRIG_SW_IRQ_ADDR
    sh      zero, (a5)                  // clear the soft device register
    lw      a5, 4(t0)
    lw      a1, 0(t0)
    csrrw   t0, mscratch, t0
    mret

    .balign 64
_trap_fail:
    li      a0, 1
    la      t0, sc_exit
    jr      t0

    .data
    .balign 4
hsave:
    .word   0
    .word   0
    .word   0
